"use geosolve sketch";
import { sketch, mm } from "@geosolve/sketch-code";

export default sketch(($) => {
  const path = $.geometry.polyline("path", {
    vertices: [{
      key: "start",
      position: [0, 0],
    }, {
      key: "bend",
      position: [20, 0],
    }, {
      key: "end",
      position: [20, 20],
    }],
  });
  const rounded = $.computed.filletSet("rounded", {
    radius: mm(2),
    corners: [{
      key: "bend",
      parents: [{
        span: path.segments.byKey.start,
        parameter: 0.9,
        winding: 0,
        neighborhood: {
          kind: "interior",
        },
        normalSide: "left",
        trimEndpoint: "end",
        periodicAnchor: {
          kind: "none",
        },
      }, {
        span: path.segments.byKey.bend,
        parameter: 0.1,
        winding: 0,
        neighborhood: {
          kind: "interior",
        },
        normalSide: "left",
        trimEndpoint: "start",
        periodicAnchor: {
          kind: "none",
        },
      }],
      endpointOrder: "firstThenSecond",
      sweep: "counterClockwise",
    }],
  });
  return {
    path: path,
    rounded: rounded,
  };
});
